package com.digithon.hr.security;

import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Generated by PI Co-Pilot: entity fields that have an encrypted copy, as entity class -> field -> column.
 * The entities themselves are not changed; PiEncryptionListener uses this while encrypted read is on.
 */
final class PiEncryptedFields {

    private static final Map<String, Map<String, String>> FIELDS = new HashMap<>();

    static {
        add("com.digithon.hr.entity.Employee", "email", "email_enc");
    }

    private PiEncryptedFields() {}

    private static void add(String entity, String field, String column) {
        FIELDS.computeIfAbsent(entity, k -> new LinkedHashMap<>()).put(field, column);
    }

    /** Field -> encrypted column for the entity, empty when it has none. */
    static Map<String, String> of(String entityName) {
        return Collections.unmodifiableMap(FIELDS.getOrDefault(entityName, Map.of()));
    }
}
